# 30_meta_common.R: metacommunity generator with two independent ecological gradients (declared before any model is evaluated; NOT tuned to maximise interaction benefit).
#   X = pH (species replacement), P = productivity (niche breadth / guild dominance). 200 species: 120 specialists (Gaussian pH niche SD 0.08, optima evenly spaced -0.05..1.05) and 80 generalists (SD 0.35, optima 0..1).
#   Expected abundance of species s at site i: w_si = pi_g(s)(P_i) * exp(-(X_i - opt_s)^2 / (2 sd_s^2)) * a_s, p_si = w_si / sum_s w_si; a_s lognormal(0, 0.5), rescaled within guild so that the guild's summed niche-weighted abundance at pH 0.5 is 1.
#   Dominance of generalists pi_gen(P): "constant" 0.5; "increasing" 0.1 + 0.8 * plogis(10 (P - 0.5)); "reversed" 0.1 + 0.8 * plogis(-10 (P - 0.5)) (specialist dominance = 1 - pi_gen).
#   Communities are generated per SITE (multinomial, N = 2000 individuals), never per sampled combination. Sites: 25 x 25 factorial pH x productivity grid with uniform jitter +-0.02 (625 sites), redrawn in each replicate.
source("revision_ident/00_ident_common.R"); source("revision_ident/01_balanced_design.R"); N_TOT <- 2000L; MSCN <- c("constant", "increasing", "reversed")
set.seed(4242); SP <- data.frame(species = sprintf("sp%03d", 1:200), guild = rep(c("specialist", "generalist"), c(120, 80)), opt = c(seq(-.05, 1.05, length.out = 120), seq(0, 1, length.out = 80)), sd = rep(c(.08, .35), c(120, 80)), a = exp(rnorm(200, 0, .5)))
for (g in c("specialist", "generalist")) { i <- SP$guild == g; SP$a[i] <- SP$a[i] / sum(SP$a[i] * exp(-.5 * ((.5 - SP$opt[i]) / SP$sd[i])^2)) }
pi_gen <- function(P, scn) switch(scn, constant = rep(.5, length(P)), increasing = .1 + .8 * plogis(10 * (P - .5)), reversed = .1 + .8 * plogis(-10 * (P - .5)))
meta_p <- function(X, P, scn) { N <- exp(-.5 * outer(X, SP$opt, "-")^2 / rep(SP$sd, each = length(X))^2) * rep(SP$a, each = length(X)); pg <- pi_gen(P, scn); isg <- SP$guild == "generalist"; W <- N; W[, isg] <- W[, isg] * pg; W[, !isg] <- W[, !isg] * (1 - pg); W / rowSums(W) }
make_sites <- function(seed) { set.seed(seed); g <- expand.grid(i = 1:25, j = 1:25); data.frame(X = (g$i - .5) / 25 + runif(625, -.02, .02), P = (g$j - .5) / 25 + runif(625, -.02, .02)) }
sample_counts <- function(env, scn) { p <- meta_p(env$X, env$P, scn); cnt <- t(vapply(seq_len(nrow(p)), function(i) rmultinom(1, N_TOT, p[i, ])[, 1], numeric(200))); colnames(cnt) <- SP$species; cnt }
resp_all <- function(cnt, idx) { ri <- ugdm_response(cnt, idx, "relative"); rt <- ugdm_response(cnt, idx, "total"); cr <- unclass(ugdm_component_response(cnt, idx)); list(incidence = rt$y, relative = ri$y, occupancy = cr[, "occupancy"], heterogeneity = cr[, "heterogeneity"], keep = rt$keep & ri$keep, trials_inc = rt$trials) }
RESP <- c("incidence", "relative", "occupancy", "heterogeneity")
# balanced sampling of real sites: cells of (mean pH, pH spread, mean productivity); several internal arrangements per cell; nearest unused sites to the target profile
bal_cells <- expand.grid(m = c(.2, .35, .5, .65, .8), h = c(.1, .2, .3, .4, .5), Pm = c(.2, .5, .8))
balanced_sites <- function(env, pool, k, n_conf, seed, tol = c(.05, .06, .1)) { set.seed(seed); E <- env[pool, , drop = FALSE]; sets <- list(); meta <- list()
  for (ci in seq_len(nrow(bal_cells))) { cl <- bal_cells[ci, ]; types <- if (k == 2) rep("pair", n_conf) else sample(rep(ARR, length.out = n_conf)); for (t in types) { q <- shape_q(k, if (t == "pair") "symmetric" else t); tx <- cl$m + cl$h * q; if (min(tx) < -.02 || max(tx) > 1.02) next; used <- integer(); for (i in seq_len(k)) { d <- ((E$X - tx[i]) / .03)^2 + ((E$P - cl$Pm) / .06)^2; d[used] <- Inf; used <- c(used, which.min(d)) }
      xs <- E$X[used]; ach <- c(abs(mean(xs) - cl$m), abs(mean(dist(xs)) - cl$h), abs(mean(E$P[used]) - cl$Pm)); if (all(ach <= tol)) { sets[[length(sets) + 1]] <- pool[used]; meta[[length(meta) + 1]] <- data.frame(cell = ci, m = cl$m, h = cl$h, Pm = cl$Pm, arrangement = t) } } }
  list(idx = do.call(rbind, sets), meta = do.call(rbind, meta)) }
# independent truth: matched profiles (pH values from an arrangement, productivity constant), Monte Carlo mean of the package response functions on simulated counts
TRUTH_GRID <- expand.grid(m = c(.35, .5, .65), h = c(.1, .2, .3), Pm = c(.2, .5, .8)); R_MC <- 200L
truth_profiles <- function(k) { set.seed(777 + k); types <- if (k == 2) "pair" else ARR; rows <- list(); meta <- list(); for (ci in seq_len(nrow(TRUTH_GRID))) for (t in types) { cl <- TRUTH_GRID[ci, ]; q <- shape_q(k, if (t == "pair") "symmetric" else t); tx <- cl$m + cl$h * q; if (min(tx) < 0 || max(tx) > 1) next; rows[[length(rows) + 1]] <- data.frame(X = tx, P = cl$Pm); meta[[length(meta) + 1]] <- cbind(cl, arrangement = t) }
  list(env = do.call(rbind, rows), idx = matrix(seq_len(k * length(rows)), length(rows), k, byrow = TRUE), meta = do.call(rbind, meta)) }
mc_truth <- function(scn, k) { tp <- truth_profiles(k); set.seed(9100 + k + 10 * match(scn, MSCN)); out <- list(); for (pi_ in seq_len(nrow(tp$idx))) { rows <- tp$idx[pi_, ]; Pm <- meta_p(tp$env$X[rows], tp$env$P[rows], scn); cnt <- do.call(rbind, lapply(seq_len(k), function(j) t(rmultinom(R_MC, N_TOT, Pm[j, ])))); idx <- matrix(rep(seq_len(R_MC), k) + rep((0:(k - 1)) * R_MC, each = R_MC), R_MC, k); colnames(cnt) <- SP$species; rr <- resp_all(cnt, idx); ok <- rr$keep
    out[[pi_]] <- data.frame(scenario = scn, order = k, tp$meta[pi_, ], incidence = mean(rr$incidence[ok]), relative = mean(rr$relative[ok]), occupancy = mean(rr$occupancy[ok]), heterogeneity = mean(rr$heterogeneity[ok]), se_relative = sd(rr$relative[ok]) / sqrt(sum(ok)), se_incidence = sd(rr$incidence[ok]) / sqrt(sum(ok))) }; do.call(rbind, out) }
